add('25_002',4,'16:9，低机位平台全景，武士黑色巨体位于画面中央上方，石铺地面占下半幅，坑沿碎板横在脚边，亮云与朝阳光线留在背后；固定机位。','武士一只手臂撑住坑边，另一侧膝部先顶起来，厚重背肩从低处抬高；踩实的脚把两粒碎石压开，他把头慢慢抬出肩线，白眼在阴影里亮成一点。话音从巨体里低沉传出，胸廓逐渐撑开，最后支撑臂从石面卸掉重量，身形将要完全站起；背后的晨光在烟雾里铺宽。','灰绿石铺地面、深灰裂坑边与米灰断板，背后蓝灰云层被中央浅金白晨光透开，稀薄米灰尘沿低处流动。','低处晨光在云雾中形成暖白背亮，巨体按原格压成深灰剪影，眼点清晰，上方冷白漫射保留少量弧面层次。','重体撑石的一声低压响，碎石两下崩开，抬身带出深长呼吸。',ja=['…新たな夜明けが来た。'],tone='武士缓慢、沉重地宣告，尾句落在抬头和胸廓撑开的时刻。',kind='mixed',phase='process',node={'叙事阶段':'武士撑起，宣告新黎明','武士.状态':'从伏地撑到半起，准备站直'},meaning='巨体撑起的剪影、地面坡入构图与晨光相接，中央亮形按阳光处理。',motion='重心由撑地臂与膝转向踩实脚，头胸从下向上抬。',ground='仍有一臂与一侧膝脚承重，镜尾向双脚站立转换。',characters=['鬼头武士'])
add('26_001',6,'16:9，武士正面头肩中近景居画面中央，椭圆头竖起，白眼落在黑隙中；镜头随最后挺身微升，落幅头顶与双肩完整。','武士把胸肩挺直，头部完全立起，白眼从下方慢慢抬到董白所在的方向；第一句说得格外笃定，肩头的擦痕仍清楚。说完他留半拍，胸廓又向外撑一点，再把第二句压向对方；狭长眼隙收紧，庞大身体在直立姿态里逐渐稳住，刚才的受伤迟滞被新的气势压下去。','头肩外是浅蓝灰云天与透雾暖白晨光，下缘米灰尘层渐淡，平台在画外。','上方冷白柔光与低处暖白晨光并存，背肩边缘稍暖，眼隙保持深黑，擦痕偏深灰。','挺身关节的低短响，胸腔沉呼吸，两句间露出空地风声。',ja=['朝は朝立ちの時間だ。','今、俺を殺そうとしても、もう遅い。'],tone='武士带夸口的笃定，第一句低沉陈述，第二句更缓、更重地威胁，末尾稳住。',kind='mixed',phase='state',node={'叙事阶段':'武士已站直并威胁','武士.状态':'恢复直立，准备聚全力'},meaning='武士正面竖头白眼与两句原作宣言完整保留，仍是言语威胁阶段。',characters=['鬼头武士'],card={'opening':'复起使武士重新认定自己占优。','beats':['站直抬眼，笃定陈述','半拍后再撑胸，缓压第二句'],'coupling':'身体立稳后才把威胁落定，仍能看见原有擦伤。','landing':'把压力交给仍在扶人的董白。'})
add('26_002',5,'16:9，董白正面脸部与扣前臂的手同框近景，青垂头在画面左侧、搭肩手臂横在下方，董白位于中央偏右；固定机位。','董白先看着武士，眼睑慢慢压成半垂，嘴轻轻一撇；她把视线斜移到肩旁闭眼的青，低声嫌弃地把话说完。青头仍垂着，手臂软软搭在她肩上；董白外侧手在前臂上重新扣牢，内侧肩向上送一点继续承重，脸上却还维持那副不满。','两人头发外露浅蓝灰云层，晨光使上缘浅暖白，下方米灰薄尘柔软。','暖白晨光给董白脸侧一线亮面，上方冷白漫射托住阴影，青银发在侧边柔亮。','董白轻轻咂气，扣前臂时护腕布料细响，青仍均匀轻呼吸。',ja=['ちっ、バカみたい。あんた、ちゃんと仕留めてないじゃない。'],tone='董白压低声音嫌弃地埋怨，话是对肩旁的青说，语尾有不服气，手上继续扶稳。',kind='mixed',phase='reaction',node={'叙事阶段':'董白扶着闭眼青，埋怨未彻底解决武士'},meaning='董白半垂眼与扶青前臂的原作接触保留，青闭眼不答话。',characters=['董白','青'],card={'opening':'她发现手柄还没有真正落袋。','beats':['看武士，眼睑压低嘴角一撇','斜看青埋怨，手重新扣牢前臂'],'coupling':'抱怨和支撑同时发生，不为训话把青放下。','landing':'她仍负担同伴，面前武士即将聚力。'})
